/* tail davi-abeid-pontes */
/* head tickets */
.entry-content #tix {
    padding-top:0
}
.page-id-13 h1, .page-id-13 h2 {
    margin-top: 0;
    line-height: 1.2;
}
.page-id-13 .tix_tickets_table {
    margin-top: 0.5rem;
}
.page-id-13 table + h2,
.page-id-13 table + p {
    margin-top:1rem;
}
.page-id-13 h1 {
    font-size: calc(1.375rem + 1.5vw);
}
.tix-alternate-payment-option label {
    padding: 0;
}

#tix .tix-submit .tix-alternate-payment-option label {
    padding: 0;
}

.tix-alternate-payment-option {display: block;min-height: 1.5rem;padding-left: 1.5em;margin-bottom: .125rem;}

.tix-alternate-payment-option input[type=radio] {
    float: left;
    margin-left: -1.5em;
}
@media (min-width: 1200px) {
    .page-id-13 h1 {
        font-size: 2.5rem;
    }
}
.page-id-13 h2 {
    font-size: calc(1.325rem + .9vw);
}
@media (min-width: 1200px) {
    .page-id-13 h2 {
        font-size: 2rem;
    }
}
.tix_tickets_table {
	width: 100%;
	margin: 0 auto;
	border-collapse: collapse;
	border-spacing: 0;
	background: white;
	border: 2px solid var(--wp--preset--color--custom-cyan-700);
	overflow: hidden;
}
table>:not(caption)>*>* {
	padding: 0.5rem 0.5rem;
}
.tix_tickets_table thead th {
	background: var(--wp--preset--color--custom-cyan-700);
	color: white;
	font-weight: 600;
	font-size: 1rem;
line-height: 1.5;
	text-transform: uppercase;
	text-align: left;
	border: none;
}
.tix-tickets-list.tix-tickets-list .tix-column-description {
font-weight: 600;
}
body.page-id-13 .tix_tickets_table tbody tr {
	border-bottom: 1px solid rgba(0, 89, 93, 0.12);
	transition: background-color 0.2s ease;
}
body.page-id-13 .tix_tickets_table tbody tr:last-child { border-bottom: none; }
body.page-id-13 .tix_tickets_table tbody tr:hover { background-color: rgba(0, 89, 93, 0.04); }

body.page-id-13 .tix_tickets_table .tix-column-description label {
	font-family: "Poppins", sans-serif;
	font-weight: 700;
	color: #00595D;
	text-transform: uppercase;
	letter-spacing: 0.3px;
}

body.page-id-13 .tix_tickets_table tbody .tix-column-price {
	font-weight: 700;
	color: #C6360B;
	white-space: nowrap;
}

.tix_tickets_table tr.tix-ticket-1995 {
    display: none!important;
}



/* Botão "Inscrever" igual aos botões do resto do site */
:where(a, button, input):focus-visible { outline:0;border:1px solid var(--wp--preset--color--custom-orange-600); outline-offset: 0; }
input[type="submit"] {
	display: inline-block;
	background-color: var(--wp--preset--color--custom-orange-600);
	color: white;
	font-weight: 700;
	font-size: 1rem;
line-height:1.5;
	text-transform: uppercase;
	border: 2px solid var(--wp--preset--color--custom-orange-600);
	border-radius: 0;
	padding: 0.375rem 0.75rem;
	cursor: pointer;
	transition: background-color 0.2s ease, transform 0.15s ease;
box-shadow:var(--wp--preset--shadow--shadow-1);
}
input[type="submit"]:focus {
outline:0;
}

input[type="submit"]:is(:hover, :focus-visible) {
    transform: translate(0.3125rem, 0.3125rem);
    box-shadow: inherit!important;
}
/* Responsivo (empilha em telas pequenas) */
@media (max-width: 600px) {
	body.page-id-13 .tix_tickets_table thead { display: none; }
	body.page-id-13 .tix_tickets_table,
	body.page-id-13 .tix_tickets_table tbody,
	body.page-id-13 .tix_tickets_table tr,
	body.page-id-13 .tix_tickets_table th,
	body.page-id-13 .tix_tickets_table td {
		display: block;
		width: 100%;
	}
	body.page-id-13 .tix_tickets_table tbody tr { padding: 12px 16px; }
	body.page-id-13 .tix_tickets_table tbody th,
	body.page-id-13 .tix_tickets_table tbody td { padding: 6px 0; }

    body.page-id-13 .tix_tickets_table .tix-column-description,
    body.page-id-13 .tix_tickets_table .tix-column-per-ticket,
    body.page-id-13 .tix_tickets_table .tix-column-quantity,
    body.page-id-13 .tix_tickets_table .tix-column-price {
        padding-block:0;
    }

    body.page-id-13 .tix_tickets_table .tix-column-description::before {
        content: "Descrição: ";
        font-weight: 700;
        color: #00595D;
    }

    body.page-id-13 .tix_tickets_table .tix-column-per-ticket::before {
        content: "Por ingresso: ";
        font-weight: 700;
        color: #00595D;
    }

    body.page-id-13 .tix_tickets_table .tix-column-quantity::before {
        content: "Quantidade: ";
        font-weight: 700;
        color: #00595D;
    }

    body.page-id-13 .tix_tickets_table .tix-column-price::before {
        content: "Preço: ";
        font-weight: 700;
        color: #00595D;
    }

    body.page-id-13 .tix_tickets_table .tix-column-remaining::before {
        content: "Restante: ";
        font-weight: 700;
        color: #00595D;
    }

    .tix-row-total .screen-reader-text {
        word-wrap: normal !important;
        border: 0;
        clip-path: unset;
        height: auto;
        margin: 0;
        overflow: hidden;
        padding: 0;
        position: static;
        width: auto;
        width: 1px;
        word-break: normal !important;
    }

    body.page-id-13 .tix_tickets_table tbody .tix-row-total td {
        padding: 0;
    }

body.page-id-13 .tix_tickets_table .tix-column-description {
        text-align: left!important;
        margin-bottom: 1rem;
    }

    body.page-id-13 .tix_tickets_table tr >*:before {
        display: inline-block;
        width: 140px!important;
    }
}

#tix form {
    margin-bottom: var(--wp--preset--spacing--80)!important;
}

#tix form tr.tix-sold-out > * {
    text-decoration: line-through;
}

#tix form tr.tix-sold-out td.tix-column-quantity {
    font-size: 0;
    text-decoration: none;
}

#tix form tr.tix-sold-out td.tix-column-quantity:before {
    content: 'Esgotado';
    font-size: 1rem;
    text-decoration: line-through;
}

