.button__back a:is(:hover, :focus-visible) {
    text-decoration: underline;
}
.wordcamp-schedule__time-slot-header:nth-of-type(odd) + .wcb-favourite-session,
.wordcamp-schedule__time-slot-header:nth-of-type(odd) + div + .wcb-favourite-session {
    background-color: #e0f8ff !important;
}

/* Palestrantes */
.wcbr-speaker-grid .wp-block-wordcamp-avatar,
.wp-block-wordcamp-avatar {
    background: radial-gradient(#bec9c800, #bec9c8);
}

.wcbr-speaker-grid ul {
    display: grid;
    grid-template-columns: repeat( auto-fit, minmax(260px, 1fr) );
    grid-gap: 3rem 2rem;
}

.wcbr-speaker-grid ul li {
    width: auto;
    margin: 0;
    justify-content: center;
    float: none;
    height: auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    align-content: flex-start;
    gap: 0.75rem 0.5rem;
}

.wcbr-speaker-grid ul li :where(*) {
    margin: 0;
}

.wcbr-speaker-grid ul li figure {
    width: 10rem!important;
    height: 10rem!important;
    float: none;
    display: block;
}
.wcbr-speaker-grid ul li img {
    --color: var(--cyan-700);
    width: 10rem;
    height: 10rem;
    float: none;
    display: block;
    object-fit: cover;
    aspect-ratio: 1!important;
    flex-shrink: 0;
    border: none;
    box-shadow: 0.3125rem 0.3125rem 0px 0 var(--color);
    border-radius: 0px;
}

/* Color 1 */
.wcbr-speaker-grid ul li:nth-child(5n+1) img {
    --color: var(--cyan-700);
}

.wcbr-speaker-grid ul li:nth-child(5n+2) img {
    --color: var(--orange-500);
}

.wcbr-speaker-grid ul li:nth-child(5n+3) img {
    --color: var(--cyan-800);
}

.wcbr-speaker-grid ul li:nth-child(5n+4) img {
    --color: var(--orange-600);
}

.wcbr-speaker-grid ul li:nth-child(5n) img {
    --color: var(--cyan-400);
}

.session-details__speaker--session ul a {
    font-weight: bold;
    line-height: 1.3em;
    text-decoration: none;
}

.session-details__speaker--session ul a:is(:hover, :focus-visible) {
    text-decoration: underline var(--wp--preset--color--accent-5);
    text-decoration-thickness: 2px!important;
    text-underline-offset: 4px;
}

.session-details__speaker--session ul p:has(a) {
    margin-bottom: 0.5rem!important;
}

.single-wcb_speaker .wp-block-wordcamp-avatar img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

/* Organizadores */
.organizers-grid li img {
    --color: var(--cyan-700);
    box-shadow: 0.3125rem 0.3125rem 0px 0 var(--color);
}

/* Color 1 */
.organizers-grid > .wp-block-group:nth-child(5n+1) img {
    --color: var(--cyan-700);
}

.organizers-grid > .wp-block-group:nth-child(5n+2) img {
    --color: var(--orange-500);
}

.organizers-grid > .wp-block-group:nth-child(5n+3) img {
    --color: var(--cyan-800);
}

.organizers-grid > .wp-block-group:nth-child(5n+4) img {
    --color: var(--orange-600);
}

.organizers-grid > .wp-block-group:nth-child(5n) img {
    --color: var(--cyan-400);
}

/* Volunteer Grid */
.grid-volunteers .grid-volunteers__volunteer img {
    --color: var(--cyan-700);
    box-shadow: 0.3125rem 0.3125rem 0px 0 var(--color);
    border-radius: 0px;
}

/* Color 1 */
.grid-volunteers .grid-volunteers__volunteer:nth-child(5n+1) img {
    --color: var(--cyan-700);
}

.grid-volunteers .grid-volunteers__volunteer:nth-child(5n+2) img {
    --color: var(--orange-500);
}

.grid-volunteers .grid-volunteers__volunteer:nth-child(5n+3) img {
    --color: var(--cyan-800);
}

.grid-volunteers .grid-volunteers__volunteer:nth-child(5n+4) img {
    --color: var(--orange-600);
}

.grid-volunteers .grid-volunteers__volunteer:nth-child(5n) img {
    --color: var(--cyan-400);
}
